import{_ as d,o as a,a as n,b as i}from"./app.DKoEZOcr.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"附录","link":"/api/appendix/appendix"},{"text":"Mmad接口边界值汇总","link":"/api/appendix/mmad_interface_boundary_value_summary"}]},"headers":[],"relativePath":"api/appendix/mmad_interface_boundary_value_summary.md","filePath":"api/appendix/mmad_interface_boundary_value_summary.md","lastUpdated":1785986301000}'),r={name:"api/appendix/mmad_interface_boundary_value_summary.md"};function f(e,t,l,o,m,p){return a(),n("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>Mmad接口边界值汇总<span id="ZH-CN_TOPIC_0000002607849175"></span></h1><p>本节汇总介绍了Mmad计算接口在边界值输入下的输出结果，数据类型见基础API下的<a href="../SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Mmad.html">mmad</a>，以下内容针对如下型号生效：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><p><strong>表1</strong> Mmad特殊值/边界值输入的计算结果说明</p><p><span id="table7822641411"></span></p><table><thead><tr><th>C矩阵的数据类型</th><th>Mmad子阶段</th><th>A矩阵的元素取值</th><th>B矩阵的元素取值</th><th>dst的元素取值<br>（INF/NAN模式）</th></tr></thead><tbody><tr><td>float</td><td>乘法阶段</td><td>+inf</td><td>norm(&gt; 0.0)/+inf</td><td>+inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>+inf</td><td>norm(&lt; 0.0)/-inf</td><td>-inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>-inf</td><td>norm(&gt; 0.0)/+inf</td><td>-inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>-inf</td><td>norm(&lt; 0.0)/-inf</td><td>+inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>+inf/-inf</td><td>0.0</td><td>nan</td></tr><tr><td>float</td><td>乘法阶段</td><td>norm(&gt; 0.0)</td><td>+inf</td><td>+inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>norm(&gt; 0.0)</td><td>-inf</td><td>-inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>norm(&lt; 0.0)</td><td>+inf</td><td>-inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>norm(&lt; 0.0)</td><td>-inf</td><td>+inf</td></tr><tr><td>float</td><td>乘法阶段</td><td>0.0</td><td>+inf/-inf</td><td>nan</td></tr><tr><td>float</td><td>乘法阶段</td><td>nan</td><td>任意输入</td><td>nan</td></tr><tr><td>float</td><td>乘法阶段</td><td>任意输入</td><td>nan</td><td>nan</td></tr><tr><td>float</td><td>乘法阶段</td><td>任意输入</td><td>任意输入</td><td>结果溢出情况下，正向溢出为inf，负向溢出为-inf</td></tr><tr><td>float</td><td>加法阶段</td><td>+inf</td><td>-inf</td><td>nan</td></tr><tr><td>float</td><td>加法阶段</td><td>+inf</td><td>+inf/norm</td><td>+inf</td></tr><tr><td>float</td><td>加法阶段</td><td>-inf</td><td>+inf</td><td>nan</td></tr><tr><td>float</td><td>加法阶段</td><td>-inf</td><td>-inf/norm</td><td>-inf</td></tr><tr><td>float</td><td>加法阶段</td><td>nan</td><td>任意输入</td><td>nan</td></tr><tr><td>float</td><td>加法阶段</td><td>任意输入</td><td>nan</td><td>nan</td></tr></tbody></table><p>注：</p><p>INF/NAN模式（非饱和模式）下，乘法阶段：inf*非零值输出inf，inf*0输出nan，输入包含nan时输出为nan。加法阶段：正负inf相加时输出为nan。</p></article></div>',1)])])}const u=d(r,[["render",f]]);export{s as __pageData,u as default};
